hidden.tests/check_query.py:
import json
import re
import sqlite3
import sys
import time

SPEC = json.load(open("tests/spec.json", encoding="utf-8"))
SCHEMA = open("tests/schema.sql", encoding="utf-8").read()
PLACES = SPEC.get("places", 4)


def build(path):
    con = sqlite3.connect(":memory:")
    con.executescript(SCHEMA)
    con.executescript(open(path, encoding="utf-8").read())
    return con


def guarded(con, sql, seconds=120):
    t0 = time.time()
    con.set_progress_handler(lambda: 1 if time.time() - t0 > seconds else 0, 100000)
    try:
        return con.execute(sql).fetchall()
    finally:
        con.set_progress_handler(None, 0)


def norm(rows, ordered):
    def nv(v):
        if isinstance(v, float):
            r = round(v, PLACES)
            return int(r) if r == int(r) else r
        if isinstance(v, bytes):
            return v.hex()
        return v
    out = [tuple(nv(v) for v in r) for r in rows]
    if not ordered:
        out.sort(key=lambda r: [(x is None, str(x)) for x in r])
    return out


def fail(msg):
    print("FAIL: " + msg)
    sys.exit(1)


def main():
    sql = open("query.sql", encoding="utf-8").read()
    body = "\n".join(l for l in sql.splitlines() if not l.strip().startswith("--")).strip()
    if not body:
        fail("query.sql is empty")
    ref = open("tests/ref.sql", encoding="utf-8").read()
    ordered = SPEC["ordered"]
    for i, path in enumerate(SPEC["datasets"], 1):
        con = build(path)
        try:
            got = guarded(con, sql)
        except sqlite3.Error as e:
            fail(f"query.sql raised {type(e).__name__}: {e}")
        want = guarded(con, ref)
        if got and len(got[0]) != len(want[0]):
            fail(f"dataset {i}: the query returns {len(got[0])} columns, expected {len(want[0])}")
        g, w = norm(got, ordered), norm(want, ordered)
        if g != w:
            extra = ""
            if len(g) != len(w):
                extra = f" (got {len(g)} rows, expected {len(w)})"
            elif ordered and sorted(map(repr, g)) == sorted(map(repr, w)):
                extra = " (right rows, wrong order)"
            else:
                bad = sum(1 for a, b in zip(g, w) if a != b)
                extra = f" ({bad} of {len(w)} rows differ)"
            fail(f"dataset {i}: result differs from the expected one{extra}")
    print(f"ok: {len(SPEC['datasets'])} datasets")


main()

hidden.tests/ref.sql:
WITH c AS (
  SELECT night, julianday(night) - ROW_NUMBER() OVER (ORDER BY night) AS g
  FROM nights WHERE weather = 'clear'
)
SELECT MIN(night) AS first_night, MAX(night) AS last_night, COUNT(*) AS nights
FROM c GROUP BY g HAVING COUNT(*) >= 3 ORDER BY first_night;

hidden.tests/schema.sql:
-- verifier copy of schema.sql
CREATE TABLE telescopes (
  tel_id        INTEGER PRIMARY KEY,
  name          TEXT NOT NULL UNIQUE,
  aperture_mm   INTEGER NOT NULL
);
CREATE TABLE targets (
  target_id    INTEGER PRIMARY KEY,
  designation  TEXT NOT NULL UNIQUE,
  kind         TEXT NOT NULL CHECK (kind IN ('galaxy', 'nebula', 'cluster', 'planet', 'variable'))
);
CREATE TABLE nights (
  night      TEXT PRIMARY KEY,           -- date the evening starts, YYYY-MM-DD; nights the dome was shut for repairs have no row
  weather    TEXT NOT NULL CHECK (weather IN ('clear', 'partial', 'cloudy', 'closed')),
  moon_pct   INTEGER NOT NULL            -- illuminated fraction of the moon, 0..100
);
CREATE TABLE sessions (
  session_id  INTEGER PRIMARY KEY,
  night       TEXT NOT NULL REFERENCES nights(night),
  tel_id      INTEGER NOT NULL REFERENCES telescopes(tel_id),
  observer    TEXT NOT NULL,
  started_at  TEXT NOT NULL,             -- 'YYYY-MM-DD HH:MM'
  ended_at    TEXT NOT NULL              -- may be on the next calendar day
);
CREATE TABLE exposures (
  exp_id      INTEGER PRIMARY KEY,
  session_id  INTEGER NOT NULL REFERENCES sessions(session_id),
  target_id   INTEGER NOT NULL REFERENCES targets(target_id),
  filter      TEXT NOT NULL CHECK (filter IN ('L', 'R', 'G', 'B', 'Ha')),
  seconds     INTEGER NOT NULL,
  started_at  TEXT NOT NULL,             -- 'YYYY-MM-DD HH:MM'
  quality     INTEGER                    -- 1 (poor) .. 5 (excellent); NULL when nobody rated the frame
);

solution.query.sql:
WITH c AS (
  SELECT night, julianday(night) - ROW_NUMBER() OVER (ORDER BY night) AS g
  FROM nights WHERE weather = 'clear'
)
SELECT MIN(night) AS first_night, MAX(night) AS last_night, COUNT(*) AS nights
FROM c GROUP BY g HAVING COUNT(*) >= 3 ORDER BY first_night;

